import { ChangeDetectionStrategy, Component, booleanAttribute, input } from '@angular/core';

@Component({
  selector: 'fieldset[aevkoRadioGroup]',
  standalone: true,
  template: '<ng-content />',
  styleUrl: './radio-group.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    '[attr.data-orientation]': 'orientation()',
    '[attr.data-invalid]': 'invalid() ? "true" : null',
  },
})
export class AevkoRadioGroup {
  readonly orientation = input<'horizontal' | 'vertical'>('vertical');
  readonly invalid = input(false, { transform: booleanAttribute });
}

@Component({
  selector: 'input[aevkoRadioGroupItem][type="radio"]',
  standalone: true,
  template: '',
  styleUrl: './radio-group-item.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { '[attr.aria-invalid]': 'invalid() ? "true" : null' },
})
export class AevkoRadioGroupItem {
  readonly invalid = input(false, { transform: booleanAttribute });
}

:host {
  border: 0;
  display: flex;
  gap: 0.75rem;
  margin: 0;
  min-inline-size: 0;
  padding: 0;
}
:host([data-orientation='vertical']) {
  flex-direction: column;
}
:host([data-orientation='horizontal']) {
  align-items: center;
  flex-wrap: wrap;
}

:host {
  appearance: none;
  background: var(--aevko-background, #fff);
  border: 1px solid var(--aevko-border-strong, #a1a1aa);
  border-radius: var(--aevko-radius, 0);
  box-sizing: border-box;
  cursor: pointer;
  display: inline-grid;
  height: 1rem;
  margin: 0;
  place-content: center;
  width: 1rem;
}
:host::after {
  background: var(--aevko-foreground, #09090b);
  content: '';
  height: 0.5rem;
  transform: scale(0);
  width: 0.5rem;
}
:host:checked::after {
  transform: scale(1);
}
:host:focus-visible {
  outline: 2px solid var(--aevko-focus, #a1a1aa);
  outline-offset: 2px;
}
:host[aria-invalid='true'] {
  border-color: var(--aevko-danger, #3f3f3f);
}
:host:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}
